#!/usr/bin/env python3
"""MCTS variants (progressive widening / expansion prior / rollout policy) on both design
spaces, same 15 starts x 5 seeds and budgets as the benchmark. Writes variants/<name>/<space>/...
configs and run_list_variants.txt for run_study.sbatch.

usage: python generate_variants.py            (all variants)
       python generate_variants.py v3 v5      (a subset)
"""
import json, sys
from pathlib import Path
import yaml
from generate_study import base, SEEDS, HERE, DATA

VARIANTS = {'v0_classic': {}, 'v5_pw1_prior_roll': {'progressive_widening': 0.5, 'pw_base': 1.0, 'expansion_prior': 'stats', 'rollout_policy': 'prior', 'rollout_epsilon': 0.2}, 'w1_a05_n3_w10': {'progressive_widening': 0.5, 'pw_base': 1.0, 'expansion_prior': 'stats', 'rollout_policy': 'prior', 'rollout_epsilon': 0.2, 'warm_start': 10, 'iterations': 3000}, 'w2_a05_n1_w10': {'progressive_widening': 0.5, 'pw_base': 1.0, 'expansion_prior': 'stats', 'rollout_policy': 'prior', 'rollout_epsilon': 0.2, 'n_rollout': 1, 'warm_start': 10, 'iterations': 3000}, 'w3_a075_n1_w10': {'progressive_widening': 0.75, 'pw_base': 1.0, 'expansion_prior': 'stats', 'rollout_policy': 'prior', 'rollout_epsilon': 0.2, 'n_rollout': 1, 'warm_start': 10, 'iterations': 3000}, 'w4_a10_n1_w10': {'progressive_widening': 1.0, 'pw_base': 1.0, 'expansion_prior': 'stats', 'rollout_policy': 'prior', 'rollout_epsilon': 0.2, 'n_rollout': 1, 'warm_start': 10, 'iterations': 3000}, 'w5_a075_n3_w10': {'progressive_widening': 0.75, 'pw_base': 1.0, 'expansion_prior': 'stats', 'rollout_policy': 'prior', 'rollout_epsilon': 0.2, 'warm_start': 10, 'iterations': 3000}, 'w6_a075_n1_w10_e05': {'progressive_widening': 0.75, 'pw_base': 1.0, 'expansion_prior': 'stats', 'rollout_policy': 'prior', 'rollout_epsilon': 0.5, 'n_rollout': 1, 'warm_start': 10, 'iterations': 3000}, 'x1_d1n1_a05_w20': {'progressive_widening': 0.5, 'pw_base': 1.0, 'expansion_prior': 'stats', 'rollout_policy': 'prior', 'rollout_epsilon': 0.2, 'rollout_depth': 1, 'n_rollout': 1, 'iterations': 3000, 'warm_start': 20}, 'x2_d1n1_a05_w10': {'progressive_widening': 0.5, 'pw_base': 1.0, 'expansion_prior': 'stats', 'rollout_policy': 'prior', 'rollout_epsilon': 0.2, 'rollout_depth': 1, 'n_rollout': 1, 'iterations': 3000, 'warm_start': 10}, 'x3_d1n1_a075_w10': {'progressive_widening': 0.75, 'pw_base': 1.0, 'expansion_prior': 'stats', 'rollout_policy': 'prior', 'rollout_epsilon': 0.2, 'rollout_depth': 1, 'n_rollout': 1, 'iterations': 3000, 'warm_start': 10}, 'x4_d1n1_a05_w5': {'progressive_widening': 0.5, 'pw_base': 1.0, 'expansion_prior': 'stats', 'rollout_policy': 'prior', 'rollout_epsilon': 0.2, 'rollout_depth': 1, 'n_rollout': 1, 'iterations': 3000, 'warm_start': 5}, 'x5_d1n1_a05_w0': {'progressive_widening': 0.5, 'pw_base': 1.0, 'expansion_prior': 'stats', 'rollout_policy': 'prior', 'rollout_epsilon': 0.2, 'rollout_depth': 1, 'n_rollout': 1, 'iterations': 3000}, 'x6_d1n1_a05_w0_it10k': {'progressive_widening': 0.5, 'pw_base': 1.0, 'expansion_prior': 'stats', 'rollout_policy': 'prior', 'rollout_epsilon': 0.2, 'rollout_depth': 1, 'n_rollout': 1, 'iterations': 10000}, 'x7_d1n1_a05_w10_it10k': {'progressive_widening': 0.5, 'pw_base': 1.0, 'expansion_prior': 'stats', 'rollout_policy': 'prior', 'rollout_epsilon': 0.2, 'rollout_depth': 1, 'n_rollout': 1, 'iterations': 10000, 'warm_start': 10}, 'y1_d2n1': {'progressive_widening': 0.5, 'pw_base': 1.0, 'expansion_prior': 'stats', 'rollout_policy': 'prior', 'rollout_epsilon': 0.2, 'rollout_depth': 2, 'n_rollout': 1, 'iterations': 3000}, 'y2_d1n2': {'progressive_widening': 0.5, 'pw_base': 1.0, 'expansion_prior': 'stats', 'rollout_policy': 'prior', 'rollout_epsilon': 0.2, 'rollout_depth': 1, 'n_rollout': 2, 'iterations': 3000}, 'y3_eps005': {'progressive_widening': 0.5, 'pw_base': 1.0, 'expansion_prior': 'stats', 'rollout_policy': 'prior', 'rollout_epsilon': 0.05, 'rollout_depth': 1, 'n_rollout': 1, 'iterations': 3000}, 'y4_eps04': {'progressive_widening': 0.5, 'pw_base': 1.0, 'expansion_prior': 'stats', 'rollout_policy': 'prior', 'rollout_epsilon': 0.4, 'rollout_depth': 1, 'n_rollout': 1, 'iterations': 3000}, 'y5_c01': {'progressive_widening': 0.5, 'pw_base': 1.0, 'expansion_prior': 'stats', 'rollout_policy': 'prior', 'rollout_epsilon': 0.2, 'rollout_depth': 1, 'n_rollout': 1, 'iterations': 3000, 'exploration_constant': 0.1}, 'y6_c10': {'progressive_widening': 0.5, 'pw_base': 1.0, 'expansion_prior': 'stats', 'rollout_policy': 'prior', 'rollout_epsilon': 0.2, 'rollout_depth': 1, 'n_rollout': 1, 'iterations': 3000, 'exploration_constant': 1.0}, 'y7_pw2': {'progressive_widening': 0.5, 'pw_base': 2.0, 'expansion_prior': 'stats', 'rollout_policy': 'prior', 'rollout_epsilon': 0.2, 'rollout_depth': 1, 'n_rollout': 1, 'iterations': 3000}, 'y8_d0': {'progressive_widening': 0.5, 'pw_base': 1.0, 'expansion_prior': 'stats', 'rollout_policy': 'prior', 'rollout_epsilon': 0.2, 'rollout_depth': 0, 'n_rollout': 0, 'iterations': 3000}, 'x8_d1n1_a05_term': {'progressive_widening': 0.5, 'pw_base': 1.0, 'expansion_prior': 'stats', 'rollout_policy': 'prior', 'rollout_epsilon': 0.2, 'rollout_depth': 1, 'n_rollout': 1, 'iterations': 3000, 'terminate_exhausted': True}, 'z1_model': {'progressive_widening': 0.5, 'pw_base': 1.0, 'expansion_prior': 'model', 'rollout_policy': 'prior', 'rollout_epsilon': 0.2, 'rollout_depth': 1, 'n_rollout': 1, 'iterations': 3000, 'acquisition': 'ucb', 'acquisition_beta': 1.0, 'model_refit_every': 25, 'terminate_exhausted': True}, 'z2_model_g1': {'progressive_widening': 0.5, 'pw_base': 1.0, 'expansion_prior': 'model', 'rollout_policy': 'prior', 'rollout_epsilon': 0.2, 'rollout_depth': 1, 'n_rollout': 1, 'iterations': 3000, 'acquisition': 'ucb', 'acquisition_beta': 1.0, 'model_refit_every': 25, 'terminate_exhausted': True, 'global_proposals': 1}, 'z3_model_g3': {'progressive_widening': 0.5, 'pw_base': 1.0, 'expansion_prior': 'model', 'rollout_policy': 'prior', 'rollout_epsilon': 0.2, 'rollout_depth': 1, 'n_rollout': 1, 'iterations': 3000, 'acquisition': 'ucb', 'acquisition_beta': 1.0, 'model_refit_every': 25, 'terminate_exhausted': True, 'global_proposals': 3}, 'z4_model_ei_g1': {'progressive_widening': 0.5, 'pw_base': 1.0, 'expansion_prior': 'model', 'rollout_policy': 'prior', 'rollout_epsilon': 0.2, 'rollout_depth': 1, 'n_rollout': 1, 'iterations': 3000, 'acquisition': 'ei', 'acquisition_beta': 1.0, 'model_refit_every': 25, 'terminate_exhausted': True, 'global_proposals': 1}, 'v1_pw': {'progressive_widening': 0.5, 'pw_base': 1.0}, 'v4_prior_only': {'expansion_prior': 'stats'}}
BUDGET = {"u_only": 54, "full": 864}
names = sys.argv[1:] or list(VARIANTS)
runs = []
ustarts = [pk for picks in json.load(open(HERE / "grid_starting_materials.json")).values() for pk in picks]
import re
fstarts = [tuple(re.match(r"([A-Z][a-z]?)([A-Z][a-z]?)6([A-Z][a-z]?)6", x["compound"]).groups()) for x in json.load(open(HERE / "full_starting_materials.json"))]
for name in names:
    opts = VARIANTS[name]
    for pk in ustarts:
        for seed in SEEDS:
            out = HERE / f"variants/{name}/u_only/{pk['material']}/seed_{seed}"
            cfg = base(pk["tm"], pk["giv"], "u_only", 3, 3, seed, out, 0.3)
            cfg["mcts"].update(opts); cfg["mcts"]["max_evaluations"] = BUDGET["u_only"]
            p = HERE / f"variants/{name}/u_only/configs/{pk['material']}_seed{seed}.yaml"; p.parent.mkdir(parents=True, exist_ok=True)
            p.write_text(yaml.safe_dump(cfg, sort_keys=False)); runs.append(str(p))
    for r_el, m_el, x_el in fstarts:
        comp = f"{r_el}{m_el}6{x_el}6"
        for seed in SEEDS:
            out = HERE / f"variants/{name}/full/{comp}/seed_{seed}"
            cfg = base(m_el, x_el, "lanthanides_u", 3, 3, seed, out, 0.3)
            cfg["intermetallic"]["structure_path"] = str(DATA / f"start_{comp}.cif")
            cfg["mcts"].update(opts); cfg["mcts"]["max_evaluations"] = BUDGET["full"]
            p = HERE / f"variants/{name}/full/configs/{comp}_seed{seed}.yaml"; p.parent.mkdir(parents=True, exist_ok=True)
            p.write_text(yaml.safe_dump(cfg, sort_keys=False)); runs.append(str(p))
(HERE / "run_list_variants.txt").write_text("\n".join(runs) + "\n")
print(len(runs), "configs for", names)
